  // ==================== Validations ====================

  async assertBookingsListLoaded(): Promise<void> {
    await expect(this.bookingManagementHeading).toBeVisible();
    await expect(this.bookingsTable).toBeVisible();
  }

  async assertBookingDetailLoaded(bookingId: string): Promise<void> {
    await expect(this.page).toHaveURL(/\/bookings\/\d+/);
    await expect(this.bookingDetailHeading).toContainText(bookingId);
  }

  async assertStatusDisplayed(rowLocator: Locator, status: string): Promise<void> {
    await expect(rowLocator).toContainText(new RegExp(status, 'i'));
  }

  async assertValidationErrorVisibleNear(fieldLocator: Locator): Promise<void> {
    await expect(this.validationErrorNear(fieldLocator)).toBeVisible();
  }

  async assertMandatoryIndicatorVisible(labelText: string): Promise<void> {
    await expect(this.page.locator(`text=${labelText}`).locator('..').getByText('*')).toBeVisible();
  }

  async assertNoMandatoryIndicator(labelText: string): Promise<void> {
    await expect(this.page.locator(`text=${labelText}`).locator('..').getByText('*')).toHaveCount(0);
  }

  async assertRoomNotOfferedForDates(roomName: string): Promise<void> {
    await expect(this.getRoomCheckbox(roomName)).toHaveCount(0);
  }

  async assertNoHorizontalOverflow(): Promise<void> {
    const hasOverflow = await this.page.evaluate(
      () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
    );
    expect(hasOverflow).toBeFalsy();
  }

  async assertEmptyStateVisible(): Promise<void> {
    await expect(this.emptyStateMessage).toBeVisible();
  }

  // ==================== Actions ====================

  /** Deep-links directly to the Bookings list — confirmed render-safe once authenticated (see book.json). */
  async navigateToBookingsList(): Promise<void> {
    await this.logInfo('Navigating to Bookings list');
    await this.page.goto(`${ConfigurationManager.config().baseUrl}/bookings`);
    await this.waitForLoadingToComplete();
  }

  async openNewBookingWizard(): Promise<void> {
    await this.withHeal(this.newBookingButton, (l) => l.click(), 'New Booking Button');
    await this.waitForLoadingToComplete();
  }

  async openBookingByRowText(text: string): Promise<void> {
    const row = this.getBookingRowByText(text);
    await this.withHeal(row, (l) => l.click(), `Booking Row (${text})`);
    await this.waitForLoadingToComplete();
  }

  async searchBookings(term: string): Promise<void> {
    await this.withHeal(this.searchBookingsInput, (l) => l.fill(term), 'Search Bookings Input');
  }

  async switchToCardView(): Promise<void> {
    await this.withHeal(this.cardViewToggleButton, (l) => l.click(), 'Card View Toggle');
  }

  async switchToTableView(): Promise<void> {
    await this.withHeal(this.tableViewToggleButton, (l) => l.click(), 'Table View Toggle');
  }

  async clickEditBooking(): Promise<void> {
    await this.withHeal(this.editBookingButton, (l) => l.click(), 'Edit Booking Button');
  }

  async clickApproveBooking(): Promise<void> {
    await this.withHeal(this.approveBookingButton, (l) => l.click(), 'Approve Booking Button');
  }

  async clickCancelBooking(): Promise<void> {
    await this.withHeal(this.cancelBookingButton, (l) => l.click(), 'Cancel Booking Button');
  }

  // -- Wizard Step 1 --
  async selectBookingType(type: 'Hunting' | 'Recreational' | 'Maintenance'): Promise<void> {
    await this.withHeal(this.getBookingTypeCard(type), (l) => l.click(), `Booking Type Card (${type})`);
  }

  async selectRanch(ranchName: string): Promise<void> {
    await this.withHeal(this.selectRanchCombobox, (l) => l.click(), 'Select Ranch Combobox');
    await this.withHeal(this.getRanchOption(ranchName), (l) => l.click(), `Ranch Option (${ranchName})`);
  }

  async selectCheckInDate(accessibleDateName: string | RegExp): Promise<void> {
    await this.withHeal(this.checkInDateButton, (l) => l.click(), 'Check-in Date Button');
    await this.withHeal(this.getCalendarDateButton(accessibleDateName), (l) => l.click(), 'Check-in Calendar Date');
  }

  async selectCheckOutDate(accessibleDateName: string | RegExp): Promise<void> {
    await this.withHeal(this.checkOutDateButton, (l) => l.click(), 'Check-out Date Button');
    await this.withHeal(this.getCalendarDateButton(accessibleDateName), (l) => l.click(), 'Check-out Calendar Date');
  }

